-- Canonical catalogs and foreign-key relations for world population cohorts.
CREATE TABLE IF NOT EXISTS public."worldOccupation" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL UNIQUE,
  "description" text,
  "active" boolean NOT NULL DEFAULT true,
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public."worldSocialClass" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL UNIQUE,
  "description" text,
  "active" boolean NOT NULL DEFAULT true,
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public."populationCohort"
  ADD COLUMN IF NOT EXISTS "raceId" integer,
  ADD COLUMN IF NOT EXISTS "occupationId" integer,
  ADD COLUMN IF NOT EXISTS "socialClassId" integer;

-- Preserve all current text values while seeding canonical catalog entries.
INSERT INTO public."worldOccupation" ("name")
SELECT DISTINCT NULLIF(btrim("occupation"), '')
FROM public."populationCohort"
WHERE NULLIF(btrim("occupation"), '') IS NOT NULL
ON CONFLICT ("name") DO NOTHING;
INSERT INTO public."worldSocialClass" ("name")
SELECT DISTINCT NULLIF(btrim("socialClass"), '')
FROM public."populationCohort"
WHERE NULLIF(btrim("socialClass"), '') IS NOT NULL
ON CONFLICT ("name") DO NOTHING;

