UPDATE public."populationCohort" c SET "raceId" = r.id
FROM public."race" r WHERE c."raceId" IS NULL AND lower(btrim(c."race")) = lower(r.name);
UPDATE public."populationCohort" c SET "occupationId" = o.id
FROM public."worldOccupation" o WHERE c."occupationId" IS NULL AND lower(btrim(c."occupation")) = lower(o.name);
UPDATE public."populationCohort" c SET "socialClassId" = s.id
FROM public."worldSocialClass" s WHERE c."socialClassId" IS NULL AND lower(btrim(c."socialClass")) = lower(s.name);

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'populationCohort_raceId_fkey') THEN
    ALTER TABLE public."populationCohort" ADD CONSTRAINT "populationCohort_raceId_fkey"
      FOREIGN KEY ("raceId") REFERENCES public."race"("id") ON DELETE SET NULL ON UPDATE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'populationCohort_occupationId_fkey') THEN
    ALTER TABLE public."populationCohort" ADD CONSTRAINT "populationCohort_occupationId_fkey"
      FOREIGN KEY ("occupationId") REFERENCES public."worldOccupation"("id") ON DELETE SET NULL ON UPDATE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'populationCohort_socialClassId_fkey') THEN
    ALTER TABLE public."populationCohort" ADD CONSTRAINT "populationCohort_socialClassId_fkey"
      FOREIGN KEY ("socialClassId") REFERENCES public."worldSocialClass"("id") ON DELETE SET NULL ON UPDATE CASCADE;
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS "populationCohort_raceId_idx" ON public."populationCohort"("raceId");
CREATE INDEX IF NOT EXISTS "populationCohort_occupationId_idx" ON public."populationCohort"("occupationId");
CREATE INDEX IF NOT EXISTS "populationCohort_socialClassId_idx" ON public."populationCohort"("socialClassId");
ALTER TABLE public."worldOccupation" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."worldSocialClass" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "worldOccupation_service_role_access" ON public."worldOccupation";
CREATE POLICY "worldOccupation_service_role_access" ON public."worldOccupation" FOR ALL TO service_role USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "worldSocialClass_service_role_access" ON public."worldSocialClass";
CREATE POLICY "worldSocialClass_service_role_access" ON public."worldSocialClass" FOR ALL TO service_role USING (true) WITH CHECK (true);
